INSERT INTO content_blocks (name, identifier, content, type, is_active, sort_order) VALUES
('Privacy - Data Collection Summary', 'privacy-data-collection-summary', '<div class="bg-blue-50 border-l-4 border-blue-500 p-6 mb-8"><h3 class="text-xl font-semibold text-blue-900 mb-3">What Data We Collect</h3><div class="grid md:grid-cols-3 gap-4"><div class="bg-white p-4 rounded-lg shadow-sm"><h4 class="font-semibold text-blue-800 mb-2">Your Account</h4><p class="text-sm text-gray-600">Email, password, profile info, API keys</p></div><div class="bg-white p-4 rounded-lg shadow-sm"><h4 class="font-semibold text-blue-800 mb-2">Your Links</h4><p class="text-sm text-gray-600">URLs, short codes, titles, QR codes</p></div><div class="bg-white p-4 rounded-lg shadow-sm"><h4 class="font-semibold text-blue-800 mb-2">Click Analytics</h4><p class="text-sm text-gray-600">IP, location, device, browser, referrer</p></div></div></div>', 'callout', true, 1),
('Privacy - Data Usage Summary', 'privacy-data-usage-summary', '<div class="bg-green-50 border-l-4 border-green-500 p-6 mb-8"><h3 class="text-xl font-semibold text-green-900 mb-3">How We Use Your Data</h3><ul class="space-y-2 text-green-800"><li class="flex items-start"><svg class="w-5 h-5 mr-2 mt-0.5 text-green-600" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"/></svg><span><strong>URL Shortening:</strong> Create and redirect your short links</span></li><li class="flex items-start"><svg class="w-5 h-5 mr-2 mt-0.5 text-green-600" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"/></svg><span><strong>Analytics:</strong> Provide click statistics and geographic data</span></li><li class="flex items-start"><svg class="w-5 h-5 mr-2 mt-0.5 text-green-600" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"/></svg><span><strong>Security:</strong> Detect malware, phishing, and abuse</span></li><li class="flex items-start"><svg class="w-5 h-5 mr-2 mt-0.5 text-green-600" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"/></svg><span><strong>Service Improvement:</strong> Optimize performance and features</span></li></ul></div>', 'callout', true, 2),
('Privacy - Quick Actions', 'privacy-quick-actions', '<div class="bg-purple-50 border border-purple-200 rounded-lg p-6 mb-8"><h3 class="text-xl font-semibold text-purple-900 mb-4">Your Privacy Controls</h3><div class="grid md:grid-cols-2 gap-4"><a href="/settings/privacy" class="flex items-center p-4 bg-white rounded-lg shadow-sm hover:shadow-md transition-shadow"><svg class="w-8 h-8 text-purple-600 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg><div><h4 class="font-semibold text-purple-900">Export Your Data</h4><p class="text-sm text-gray-600">Download all your links and analytics</p></div></a><a href="/settings/account" class="flex items-center p-4 bg-white rounded-lg shadow-sm hover:shadow-md transition-shadow"><svg class="w-8 h-8 text-purple-600 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg><div><h4 class="font-semibold text-purple-900">Delete Account</h4><p class="text-sm text-gray-600">Remove all your data permanently</p></div></a></div></div>', 'cta', true, 3),
('Terms - Service Overview', 'terms-service-overview', '<div class="bg-indigo-50 border-l-4 border-indigo-500 p-6 mb-8"><h3 class="text-xl font-semibold text-indigo-900 mb-3">What Trunc Provides</h3><div class="grid md:grid-cols-2 gap-6"><div><h4 class="font-semibold text-indigo-800 mb-2">Core Features</h4><ul class="text-sm text-gray-700 space-y-1"><li>• URL shortening with custom aliases</li><li>• Real-time click analytics</li><li>• Geographic & device tracking</li><li>• QR code generation</li><li>• Link management dashboard</li></ul></div><div><h4 class="font-semibold text-indigo-800 mb-2">Advanced Features</h4><ul class="text-sm text-gray-700 space-y-1"><li>• RESTful API access</li><li>• Bulk operations</li><li>• Custom domain support</li><li>• Link expiration & passwords</li><li>• Team collaboration</li></ul></div></div></div>', 'callout', true, 4),
('Terms - Prohibited Content', 'terms-prohibited-content', '<div class="bg-red-50 border border-red-200 rounded-lg p-6 mb-8"><h3 class="text-xl font-semibold text-red-900 mb-4">⚠️ Prohibited Link Destinations</h3><p class="text-red-800 mb-4">You may NOT use Trunc to create short links to:</p><div class="grid md:grid-cols-2 gap-4"><div class="bg-white p-4 rounded-lg border-l-4 border-red-400"><h4 class="font-semibold text-red-900 mb-2">Illegal Content</h4><ul class="text-sm text-red-800 space-y-1"><li>• Pirated software or media</li><li>• Illegal drugs or substances</li><li>• Counterfeit goods</li><li>• Illegal weapons sales</li></ul></div><div class="bg-white p-4 rounded-lg border-l-4 border-red-400"><h4 class="font-semibold text-red-900 mb-2">Malicious Sites</h4><ul class="text-sm text-red-800 space-y-1"><li>• Malware or viruses</li><li>• Phishing or scam sites</li><li>• Exploit kits</li><li>• Ransomware distribution</li></ul></div><div class="bg-white p-4 rounded-lg border-l-4 border-red-400"><h4 class="font-semibold text-red-900 mb-2">Harmful Content</h4><ul class="text-sm text-red-800 space-y-1"><li>• Violence or gore</li><li>• Hate speech</li><li>• Child endangerment</li><li>• Harassment campaigns</li></ul></div><div class="bg-white p-4 rounded-lg border-l-4 border-red-400"><h4 class="font-semibold text-red-900 mb-2">Deceptive Practices</h4><ul class="text-sm text-red-800 space-y-1"><li>• Spam or unsolicited ads</li><li>• Ponzi or pyramid schemes</li><li>• Fake news or misinformation</li><li>• Clickbait or misleading links</li></ul></div></div><p class="mt-4 text-sm text-red-700"><strong>Violation = Immediate Account Termination</strong></p></div>', 'warning', true, 5),
('Terms - Link Management Policies', 'terms-link-policies', '<div class="bg-yellow-50 border-l-4 border-yellow-500 p-6 mb-8"><h3 class="text-xl font-semibold text-yellow-900 mb-3">Link Management Policies</h3><div class="space-y-4"><div class="flex items-start"><div class="flex-shrink-0 w-8 h-8 bg-yellow-200 rounded-full flex items-center justify-center text-yellow-900 font-bold">1</div><div class="ml-4"><h4 class="font-semibold text-yellow-900">Link Ownership</h4><p class="text-sm text-gray-700">You retain ownership of your links and destination content. We only store short codes and analytics.</p></div></div><div class="flex items-start"><div class="flex-shrink-0 w-8 h-8 bg-yellow-200 rounded-full flex items-center justify-center text-yellow-900 font-bold">2</div><div class="ml-4"><h4 class="font-semibold text-yellow-900">Link Expiration</h4><p class="text-sm text-gray-700">Free links remain active for 2 years of inactivity. Paid plans: indefinite. Set custom expiration dates anytime.</p></div></div><div class="flex items-start"><div class="flex-shrink-0 w-8 h-8 bg-yellow-200 rounded-full flex items-center justify-center text-yellow-900 font-bold">3</div><div class="ml-4"><h4 class="font-semibold text-yellow-900">Link Deletion</h4><p class="text-sm text-gray-700">Deleted links enter 30-day recovery period. After 30 days, short codes may be reassigned to new users.</p></div></div><div class="flex items-start"><div class="flex-shrink-0 w-8 h-8 bg-yellow-200 rounded-full flex items-center justify-center text-yellow-900 font-bold">4</div><div class="ml-4"><h4 class="font-semibold text-yellow-900">Malicious Link Detection</h4><p class="text-sm text-gray-700">We scan destination URLs for malware/phishing. Malicious links are automatically disabled and may result in account suspension.</p></div></div></div></div>', 'policy', true, 6),
('Terms - API Usage Terms', 'terms-api-usage', '<div class="bg-cyan-50 border border-cyan-200 rounded-lg p-6 mb-8"><h3 class="text-xl font-semibold text-cyan-900 mb-4">API Usage Terms</h3><div class="grid md:grid-cols-3 gap-4 mb-4"><div class="bg-white p-4 rounded-lg text-center"><div class="text-3xl font-bold text-cyan-600 mb-1">1,000</div><p class="text-sm text-gray-600">Free Plan Requests/Month</p></div><div class="bg-white p-4 rounded-lg text-center"><div class="text-3xl font-bold text-cyan-600 mb-1">50,000</div><p class="text-sm text-gray-600">Pro Plan Requests/Month</p></div><div class="bg-white p-4 rounded-lg text-center"><div class="text-3xl font-bold text-cyan-600 mb-1">∞</div><p class="text-sm text-gray-600">Enterprise Unlimited</p></div></div><div class="bg-white p-4 rounded-lg"><h4 class="font-semibold text-cyan-900 mb-2">API Requirements</h4><ul class="text-sm text-gray-700 space-y-1"><li>• Include API key in Authorization header</li><li>• Rate limit: 100 requests per minute</li><li>• Respect HTTP 429 (Too Many Requests) responses</li><li>• Use exponential backoff for retries</li><li>• Keep API keys secure and rotate regularly</li></ul></div></div>', 'info', true, 7),
('Terms - Service Level Agreement', 'terms-sla', '<div class="bg-teal-50 border-l-4 border-teal-500 p-6 mb-8"><h3 class="text-xl font-semibold text-teal-900 mb-3">Service Level Agreement (SLA)</h3><div class="grid md:grid-cols-2 gap-6"><div><h4 class="font-semibold text-teal-800 mb-3">Uptime Guarantee</h4><div class="space-y-2"><div class="flex justify-between items-center p-2 bg-white rounded"><span class="text-sm font-medium">Target Uptime:</span><span class="text-lg font-bold text-teal-600">99.9%</span></div><div class="flex justify-between items-center p-2 bg-white rounded"><span class="text-sm font-medium">Max Monthly Downtime:</span><span class="text-lg font-bold text-teal-600">43.8 min</span></div><div class="flex justify-between items-center p-2 bg-white rounded"><span class="text-sm font-medium">Redirect Response:</span><span class="text-lg font-bold text-teal-600">&lt;100ms</span></div></div></div><div><h4 class="font-semibold text-teal-800 mb-3">Maintenance Windows</h4><p class="text-sm text-gray-700 mb-2">Scheduled maintenance occurs:</p><ul class="text-sm text-gray-700 space-y-1"><li>• Tuesdays 2-4 AM UTC</li><li>• 48-hour advance notice</li><li>• Status page updates</li><li>• Email notifications sent</li></ul><p class="text-xs text-gray-600 mt-3"><strong>Note:</strong> Emergency maintenance may occur without notice for security patches.</p></div></div></div>', 'info', true, 8),
('Privacy & Terms - Contact CTA', 'privacy-terms-contact-cta', '<div class="bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-lg p-8 text-center"><h3 class="text-2xl font-bold mb-3">Have Questions About Our Policies?</h3><p class="text-blue-100 mb-6">Our legal and privacy teams are here to help you understand your rights and our practices.</p><div class="flex flex-col sm:flex-row gap-4 justify-center"><a href="/contact" class="bg-white text-blue-600 px-6 py-3 rounded-lg font-semibold hover:bg-blue-50 transition-colors">Contact Support</a><a href="mailto:legal@urlshorter.com" class="border-2 border-white text-white px-6 py-3 rounded-lg font-semibold hover:bg-white hover:text-blue-600 transition-colors">Email Legal Team</a></div></div>', 'cta', true, 9)
ON CONFLICT (identifier) DO NOTHING;

